import { useState, useEffect } from "react";
import Login from "./pages/Login";
import Dashboard from "./pages/Dashboard";
import Transactions from "./pages/Transactions";
import Budgets from "./pages/Budgets";
import Analytics from "./pages/Analytics";
import AIInsights from "./pages/AIInsights";
import { getMe } from "./services/api";

const NAV = [
  { id: "dashboard",    label: "Dashboard",    icon: "◈" },
  { id: "transactions", label: "Transactions",  icon: "⇄" },
  { id: "budgets",      label: "Budgets",       icon: "◎" },
  { id: "analytics",   label: "Analytics",     icon: "∿" },
  { id: "ai",          label: "AI Insights",   icon: "⬡" },
];

const G = {
  bg:      "#050a14",
  surface: "#0c1526",
  border:  "#1a2840",
  accent:  "#00d4ff",
  accent2: "#7c3aed",
  green:   "#00ff9d",
  red:     "#ff4d6d",
  yellow:  "#ffd60a",
  text:    "#e2eaf5",
  muted:   "#4a6080",
  font:    "'Outfit', sans-serif",
  mono:    "'JetBrains Mono', monospace",
};

export { G };

export default function App() {
  const [user, setUser]       = useState(null);
  const [page, setPage]       = useState("dashboard");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) {
      getMe()
        .then(r => setUser(r.data))
        .catch(() => localStorage.removeItem("token"))
        .finally(() => setLoading(false));
    } else {
      setLoading(false);
    }
  }, []);

  const handleLogin = (userData, token) => {
    localStorage.setItem("token", token);
    setUser(userData);
  };

  const handleLogout = () => {
    localStorage.removeItem("token");
    setUser(null);
  };

  const s = {
    app: {
      minHeight: "100vh",
      background: G.bg,
      color: G.text,
      fontFamily: G.font,
      display: "flex",
    },
    sidebar: {
      width: 220,
      background: G.surface,
      borderRight: `1px solid ${G.border}`,
      display: "flex",
      flexDirection: "column",
      padding: "0",
      flexShrink: 0,
      position: "fixed",
      top: 0, left: 0, bottom: 0,
    },
    logo: {
      padding: "28px 24px 20px",
      borderBottom: `1px solid ${G.border}`,
    },
    logoText: {
      fontFamily: G.font,
      fontWeight: 900,
      fontSize: 18,
      background: `linear-gradient(135deg, ${G.accent}, ${G.accent2})`,
      WebkitBackgroundClip: "text",
      WebkitTextFillColor: "transparent",
      letterSpacing: "-0.5px",
    },
    logoSub: {
      fontSize: 10,
      color: G.muted,
      letterSpacing: 2,
      textTransform: "uppercase",
      marginTop: 2,
    },
    nav: {
      padding: "16px 12px",
      flex: 1,
    },
    navBtn: (active) => ({
      display: "flex",
      alignItems: "center",
      gap: 10,
      width: "100%",
      padding: "10px 14px",
      borderRadius: 10,
      border: "none",
      cursor: "pointer",
      marginBottom: 4,
      background: active ? `${G.accent}18` : "transparent",
      color: active ? G.accent : G.muted,
      fontSize: 13,
      fontWeight: active ? 600 : 400,
      fontFamily: G.font,
      textAlign: "left",
      transition: "all 0.15s",
      borderLeft: active ? `3px solid ${G.accent}` : "3px solid transparent",
    }),
    navIcon: {
      fontSize: 16,
      width: 20,
      textAlign: "center",
      flexShrink: 0,
    },
    userBox: {
      padding: "16px",
      borderTop: `1px solid ${G.border}`,
    },
    userInfo: {
      fontSize: 12,
      color: G.muted,
      marginBottom: 8,
      overflow: "hidden",
      textOverflow: "ellipsis",
      whiteSpace: "nowrap",
    },
    userName: {
      fontWeight: 600,
      color: G.text,
      fontSize: 13,
    },
    logoutBtn: {
      width: "100%",
      padding: "8px",
      background: `${G.red}15`,
      border: `1px solid ${G.red}30`,
      borderRadius: 8,
      color: G.red,
      fontSize: 12,
      fontWeight: 600,
      cursor: "pointer",
      fontFamily: G.font,
    },
    main: {
      flex: 1,
      marginLeft: 220,
      padding: "32px",
      minHeight: "100vh",
      maxWidth: "calc(100vw - 220px)",
    },
  };

  if (loading) return (
    <div style={{ ...s.app, alignItems: "center", justifyContent: "center" }}>
      <div style={{ color: G.accent, fontFamily: G.mono, fontSize: 14 }}>Loading...</div>
    </div>
  );

  if (!user) return <Login onLogin={handleLogin} />;

  const pages = { dashboard: Dashboard, transactions: Transactions, budgets: Budgets, analytics: Analytics, ai: AIInsights };
  const PageComponent = pages[page] || Dashboard;

  return (
    <div style={s.app}>
      <style>{`
        * { box-sizing: border-box; margin: 0; padding: 0; }
        ::-webkit-scrollbar { width: 5px; }
        ::-webkit-scrollbar-track { background: ${G.bg}; }
        ::-webkit-scrollbar-thumb { background: ${G.border}; border-radius: 3px; }
        button:hover { opacity: 0.85; }
        input, select { outline: none; }
        @keyframes fadeIn { from { opacity:0; transform:translateY(8px); } to { opacity:1; transform:translateY(0); } }
        .fade-in { animation: fadeIn 0.3s ease forwards; }
        @keyframes pulse { 0%,100% { opacity:1; } 50% { opacity:0.5; } }
      `}</style>

      {/* Sidebar */}
      <aside style={s.sidebar}>
        <div style={s.logo}>
          <div style={s.logoText}>ExpenseIQ</div>
          <div style={s.logoSub}>Smart Tracker</div>
        </div>

        <nav style={s.nav}>
          {NAV.map(n => (
            <button key={n.id} style={s.navBtn(page === n.id)} onClick={() => setPage(n.id)}>
              <span style={s.navIcon}>{n.icon}</span>
              {n.label}
            </button>
          ))}
        </nav>

        <div style={s.userBox}>
          <div style={s.userName}>{user.name}</div>
          <div style={s.userInfo}>{user.email}</div>
          <button style={s.logoutBtn} onClick={handleLogout}>Sign Out</button>
        </div>
      </aside>

      {/* Main content */}
      <main style={s.main}>
        <PageComponent user={user} />
      </main>
    </div>
  );
}
